<?php require __DIR__.'/../bootstrap.php';require_login();$uid=current_user()['id'];$id=(int)getv('id');$s=db()->prepare('SELECT * FROM projects WHERE id=? AND user_id=?');$s->execute([$id,$uid]);$p=$s->fetch();if(!$p)exit('Project not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE projects SET name=?,description=?,status=?,start_date=?,due_date=?,updated_at=NOW() WHERE id=? AND user_id=?')->execute([post('name'),post('description'),post('status'),post('start_date')?:null,post('due_date')?:null,$id,$uid]);redirect('/projects/');}$title='Edit Project';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Name<input name="name" value="<?=e($p['name'])?>" required></label><label>Description<textarea name="description" rows="6"><?=e($p['description'])?></textarea></label><label>Status<select name="status"><?php foreach(['Planning','Active','Completed','Archived'] as $v):?><option <?=$p['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><div class="actions"><button class="btn edit-btn" style="background:var(--brand)!important;color:#fff!important">Save Changes</button><button class="btn danger" type="submit" formaction="/projects/delete/" formmethod="post" name="id" value="<?=$id?>">Delete Project</button></div><p><a class="btn secondary small" href="/ai/?prompt=Project%20assist%3A%20help%20me%20improve%20this%20project">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>